async function main() {
  const procs = await tools.process.list();
  const ids = (procs as any).processes ? (procs as any).processes.map((p: any) => p.processId) : [];
  const stopped: string[] = [];
  for (const id of ids) {
    await tools.process.stop({ processId: id });
    stopped.push(id);
  }
  return { stopped };
}
